#!/usr/bin/env python3
"""Recreate the saved 200-post r/CasualConversation CSV.

Run: python3 generate_casual_posts.py
Or:  python3 generate_casual_posts.py --output /tmp/casual_posts.csv

The original posts were collected from publicly readable Reddit pages using
browser tools. This script embeds that collected snapshot and regenerates
its exact CSV bytes without network access or additional data files. It does
not scrape fresh posts or invent new examples. The saved labels are AI-assigned
preliminary annotations; human review is pending and disclosed in each note. Each row includes its original
public source URL. Sampling combined recent/ranked feeds and related-post
links; it is a convenience sample, not a random sample of the community.
Rendered text can differ from raw Reddit Markdown in layout and whitespace.

Existing output is verified if identical; different files are never overwritten.
Uses Python's standard library only.
"""

import argparse
import base64
import csv
import hashlib
import io
from pathlib import Path
import re
import unicodedata
import zlib


def normalize(text):
    return " ".join(unicodedata.normalize("NFKC", text).casefold().split())


def snapshot():
    payload = zlib.decompress(base64.b64decode(SNAPSHOT))
    if hashlib.sha256(payload).hexdigest() != SHA256:
        raise ValueError("Embedded snapshot checksum mismatch")
    rows = list(csv.DictReader(io.StringIO(payload.decode("utf-8-sig"), newline="")))
    if len(rows) != 200:
        raise ValueError("Expected exactly 200 posts")
    for key in ("id", "source_url", "text", "body"):
        values = [normalize(row[key]) for row in rows]
        if any(not value for value in values) or len(set(values)) != 200:
            raise ValueError(f"Empty or duplicate values in {key}")
    unavailable_markers = (
        "sorry, this post was removed", "post is awaiting moderator approval",
        "this post was mass deleted and anonymized", "[removed]", "[deleted]",
    )
    for row in rows:
        body = row["body"].casefold()
        if any(marker in body for marker in unavailable_markers):
            raise ValueError("Unavailable original body in snapshot")
        match = re.fullmatch(
            r"https://www\.reddit\.com/r/CasualConversation/comments/([a-z0-9]+)/[^?#]*",
            row["source_url"],
        )
        if not match or match[1] != row["id"]:
            raise ValueError("Source URL does not match post ID")
        if (row["community"] != "r/CasualConversation"
                or row["post_type"] != "main_post"
                or row["text"] != row["title"] + "\n\n" + row["body"]
                or row["label"] not in {"personal_experience", "discussion_request", "viewpoint"}
                or not row["note"].startswith("AI-prelabeled; human review pending.")):
            raise ValueError("Invalid original post, label, or annotation disclosure")
    return payload


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output", type=Path,
        default=Path(__file__).resolve().parent / "data/casualconversation_posts.csv",
    )
    args = parser.parse_args()
    payload = snapshot()
    if args.output.exists():
        if args.output.read_bytes() != payload:
            parser.error(f"{args.output} exists with different contents; choose another --output")
        print(f"Verified {args.output}")
    else:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        with args.output.open("xb") as stream:
            stream.write(payload)
        print(f"Generated {args.output}")
    print("200 posts; 200 unique IDs, URLs, normalized texts, and bodies; three AI-prelabeled categories.")
    print(f"SHA-256: {SHA256}")
    return 0


